//! macOS 实现：`NSPasteboard.generalPasteboard`。
//!
//! - 读：纯文本、HTML、RTF、PNG（只有 TIFF 时转成 PNG）、文件（`public.file-url`，展开成清单，规则见
//!   `files`）。先看 `types`（不会触发系统的剪贴板隐私提示），只读取本项目支持的类型。读前后比较
//!   `changeCount`，保证一次读到的是同一份内容。
//! - 隐私标记（nspasteboard.org）：`org.nspasteboard.TransientType` > `ConcealedType` > `AutoGeneratedType`，
//!   同时识别旧的等价类型；精确标记经 Custom 保留，Sensitivity 仅作摘要与旧接口兼容。
//! - 写：`clearContents` + `writeObjects:`，每个文件一个 `NSPasteboardItem`（只写顶层条目的 URL），其他表示形式
//!   放在第一个条目上；返回写完后的 `changeCount`。文本里的 CRLF 转成 LF。
//! - 远端文件：File Provider 占位 URL，粘贴读取时由系统触发内容拉取。
//! - 监听：macOS 没有剪贴板变化通知，后台线程每 200 ms 轮询 `changeCount`。

mod clipboard_key;
mod content;
pub(crate) mod dnd;
pub mod file_provider;
mod files;
mod pasteboard;
#[cfg(all(test, debug_assertions))]
mod test_pasteboard;
mod thumbnail;

#[cfg(all(test, debug_assertions))]
pub(crate) fn run_native_linked_promise_tests() {
    dnd::proxy::linked_tests::run();
}

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread::JoinHandle;
use std::time::Duration;

use crate::{
    ChangeHandler, ClipData, ClipSnapshot, ClipboardBackend, ClipboardError, FileContents, FileEntry, Sensitivity,
};

/// 轮询间隔（契约要求 ≤ 250 ms）。
pub(crate) const POLL_INTERVAL: Duration = Duration::from_millis(200);

pub(crate) fn backend() -> Result<Box<dyn ClipboardBackend>, ClipboardError> {
    Ok(Box::new(MacClipboard {
        name: None,
        watcher: Mutex::new(None),
        registration: Arc::new(Mutex::new(None)),
        local: Arc::new(Mutex::new(None)),
    }))
}

struct MacClipboard {
    /// Production uses the system clipboard; tests construct a private named board.
    name: Option<String>,
    watcher: Mutex<Option<Watcher>>,
    registration: Arc<Mutex<Option<(u64, file_provider::Registration)>>>,
    local: Arc<Mutex<Option<(u64, crate::store::Batch)>>>,
}

impl ClipboardBackend for MacClipboard {
    fn clipboard_key(&self) -> std::io::Result<[u8; 32]> {
        clipboard_key::current(self.name.as_deref())
    }
    fn initialize_store(&self, data: std::path::PathBuf) {
        file_provider::initialize(data);
    }
    fn change_count(&self) -> u64 {
        pasteboard::change_count(self.name.as_deref())
    }

    fn read(&self) -> Result<ClipSnapshot, ClipboardError> {
        pasteboard::read(self.name.as_deref())
    }

    fn capture(&self, data: &std::path::Path) -> Result<crate::CapturedClipboard, ClipboardError> {
        content::capture(self.name.as_deref(), data)
    }

    fn write_native(&self, spec: crate::NativeSpec) -> Result<u64, ClipboardError> {
        self.write_native_guarded(spec, std::sync::Arc::new(|| Ok(())))
    }
    fn write_native_guarded(
        &self,
        mut spec: crate::NativeSpec,
        guard: crate::content::ReaderGuard,
    ) -> Result<u64, ClipboardError> {
        let before = self.change_count();
        spec.prepare_promises()
            .map_err(|error| ClipboardError::ContentUnavailable(crate::content::reason(&error)))?;
        let registration = if spec.files.is_empty() || spec.file_contents.is_none() {
            None
        } else {
            let source = spec.file_contents.clone().ok_or(ClipboardError::Unsupported)?;
            Some(
                file_provider::publish(&spec.files, source, Duration::from_secs(12)).map_err(|error| match error {
                    ClipboardError::FileProvider(_) | ClipboardError::ContentUnavailable(_) => error,
                    _ => ClipboardError::FileProviderUnavailable,
                })?,
            )
        };
        if self.change_count() != before {
            return Err(ClipboardError::Busy);
        }
        let mut urls = std::collections::HashMap::new();
        if !spec.files.is_empty() {
            let entries = registration
                .as_ref()
                .map_or(spec.files.as_slice(), |registration| registration.entries());
            let paths: Vec<_> = entries
                .iter()
                .filter(|entry| files::is_top_level(entry))
                .filter_map(|entry| entry.local_path.as_deref())
                .collect();
            let nodes: Vec<_> = spec.inventory.roots.iter().map(|node| node.id).collect();
            if nodes.len() != paths.len() {
                return Err(ClipboardError::Unsupported);
            }
            for (node, path) in nodes.into_iter().zip(paths) {
                urls.insert(node, pasteboard::file_url_string(path));
            }
        }
        let count = content::write(self.name.as_deref(), &spec, &urls, guard.as_ref())?;
        *self.registration.lock().unwrap() = registration.map(|registration| (count, registration));
        *self.local.lock().unwrap() = if spec.file_contents.is_none() && !spec.files.is_empty() {
            spec.contents.local_batch().map(|batch| (count, batch))
        } else {
            None
        };
        Ok(count)
    }

    fn write(&self, items: &[ClipData], sensitivity: Sensitivity) -> Result<u64, ClipboardError> {
        let cc = pasteboard::write(self.name.as_deref(), items, sensitivity)?;
        *self.registration.lock().unwrap_or_else(|e| e.into_inner()) = None;
        *self.local.lock().unwrap_or_else(|e| e.into_inner()) = None;
        Ok(cc)
    }

    /// Publish File Provider URLs; failures return to the size-limited prefetch policy.
    fn write_virtual_files(
        &self,
        entries: &[FileEntry],
        others: &[ClipData],
        contents: Arc<dyn FileContents>,
        sensitivity: Sensitivity,
    ) -> Result<u64, ClipboardError> {
        let before = self.change_count();
        let registration = file_provider::publish(entries, contents, Duration::from_secs(12))?;
        if self.change_count() != before {
            registration.cancel();
            return Err(ClipboardError::Busy);
        }
        let mut items = others.to_vec();
        items.push(ClipData::Files(registration.entries().to_vec()));
        match self.write(&items, sensitivity) {
            Ok(count) => {
                *self.registration.lock().unwrap_or_else(|e| e.into_inner()) = Some((count, registration));
                Ok(count)
            }
            Err(e) => {
                registration.cancel();
                Err(e)
            }
        }
    }

    fn set_watch_paused(&self, paused: bool) -> Result<(), ClipboardError> {
        if let Some(watcher) = self.watcher.lock().unwrap_or_else(|e| e.into_inner()).as_ref() {
            *watcher.paused.0.lock().unwrap_or_else(|e| e.into_inner()) = paused;
            watcher.paused.1.notify_all();
        }
        if paused && let Some((_, registration)) = self.registration.lock().unwrap_or_else(|e| e.into_inner()).take() {
            registration.cancel();
        }
        Ok(())
    }

    fn watch(&self, on_change: ChangeHandler) -> Result<(), ClipboardError> {
        let mut w = self.watcher.lock().unwrap_or_else(|e| e.into_inner());
        match w.as_ref() {
            Some(existing) => existing
                .handlers
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .push(on_change),
            None => {
                *w = Some(Watcher::start(
                    self.name.clone(),
                    on_change,
                    self.registration.clone(),
                    self.local.clone(),
                )?)
            }
        }
        Ok(())
    }
}

struct Watcher {
    paused: Arc<(Mutex<bool>, std::sync::Condvar)>,
    handlers: Arc<Mutex<Vec<ChangeHandler>>>,
    stop: Arc<AtomicBool>,
    thread: Option<JoinHandle<()>>,
}

impl Watcher {
    fn start(
        name: Option<String>,
        first: ChangeHandler,
        registration: Arc<Mutex<Option<(u64, file_provider::Registration)>>>,
        local: Arc<Mutex<Option<(u64, crate::store::Batch)>>>,
    ) -> Result<Self, ClipboardError> {
        let handlers = Arc::new(Mutex::new(vec![first]));
        let stop = Arc::new(AtomicBool::new(false));
        let paused = Arc::new((Mutex::new(false), std::sync::Condvar::new()));
        let pause = paused.clone();
        let (h, s) = (handlers.clone(), stop.clone());
        let thread = std::thread::Builder::new()
            .name("oink-clipboard-watch".into())
            .spawn(move || {
                let mut last = pasteboard::change_count(name.as_deref());
                while !s.load(Ordering::Acquire) {
                    let guard = pause.0.lock().unwrap_or_else(|e| e.into_inner());
                    let guard = pause
                        .1
                        .wait_while(guard, |paused| *paused && !s.load(Ordering::Acquire))
                        .unwrap_or_else(|e| e.into_inner());
                    if s.load(Ordering::Acquire) {
                        return;
                    }
                    let (guard, _) = pause
                        .1
                        .wait_timeout(guard, POLL_INTERVAL)
                        .unwrap_or_else(|e| e.into_inner());
                    if *guard || s.load(Ordering::Acquire) {
                        continue;
                    }
                    drop(guard);
                    let cur = pasteboard::change_count(name.as_deref());
                    if cur != last {
                        last = cur;
                        let mut held = registration.lock().unwrap_or_else(|e| e.into_inner());
                        if held.as_ref().is_some_and(|(count, _)| *count != cur) {
                            *held = None;
                        }
                        drop(held);
                        let mut held = local.lock().unwrap_or_else(|e| e.into_inner());
                        if held.as_ref().is_some_and(|(count, _)| *count != cur) {
                            *held = None;
                        }
                        drop(held);
                        let list = h.lock().unwrap_or_else(|e| e.into_inner()).clone();
                        for f in list {
                            f();
                        }
                    }
                }
            })
            .map_err(|e| ClipboardError::Platform(format!("创建线程失败：{e}")))?;
        Ok(Self {
            paused,
            handlers,
            stop,
            thread: Some(thread),
        })
    }
}

impl Drop for Watcher {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        self.paused.1.notify_all();
        if let Some(t) = self.thread.take() {
            let _ = t.join();
        }
    }
}

#[cfg(all(test, debug_assertions))]
mod tests {
    use super::*;

    struct NoContents;
    impl FileContents for NoContents {
        fn open(&self, _index: usize) -> std::io::Result<Box<dyn std::io::Read + Send>> {
            Err(std::io::Error::other("测试里不应读取内容"))
        }
    }

    fn entry(path: &str, is_dir: bool, size: u64) -> FileEntry {
        FileEntry {
            path: path.into(),
            is_dir,
            size,
            modified_ms: None,
            local_path: None,
        }
    }

    /// A standalone test executable has no signed File Provider manager.
    #[test]
    fn virtual_files_fail_without_signed_manager() {
        let clip = MacClipboard {
            name: Some(format!("com.hachiwii.oink.test.virtual.{}", std::process::id())),
            watcher: Mutex::new(None),
            registration: Arc::new(Mutex::new(None)),
            local: Arc::new(Mutex::new(None)),
        };
        let entries = vec![
            entry("Docs", true, 0),
            entry("Docs/a.txt", false, 10),
            entry("b.txt", false, 5),
        ];
        assert!(
            clip.write_virtual_files(&entries, &[], Arc::new(NoContents), Sensitivity::Normal,)
                .is_err()
        );
        assert!(
            clip.write_virtual_files(&[], &[], Arc::new(NoContents), Sensitivity::Normal)
                .is_err()
        );
    }
}
